('hu','/flags/history/hu-1956.svg','1956-11-12'::date,'1957-05-22'::date,'Flag of Hungary (1946-1949, 1956-1957)','Drapeau (1956–1957)','Source: Wikimedia Commons (Public domain — Thommy). https://commons.wikimedia.org/wiki/File:Flag_of_Hungary_(1946-1949,_1956-1957).svg','Source : Wikimedia Commons (Public domain — Thommy). https://commons.wikimedia.org/wiki/File:Flag_of_Hungary_(1946-1949,_1956-1957).svg')
) v(iso, img, ds, de, le, lf, ne, nf)
where not exists (
  select 1 from country_flag_history h
  where h.iso_code = v.iso
    and h.date_start is not null
    and abs(extract(year from h.date_start) - extract(year from v.ds)) <= 1
    and abs(coalesce(extract(year from h.date_end), 9999) - extract(year from v.de)) <= 1);